def inventory(config, source, stopped=lambda: False):
    path = config.source(source["path"])
    rows = {}

    def walk(fd, prefix=""):
        before = signature(os.fstat(fd))
        with os.scandir(fd) as entries:
            names = sorted(e.name for e in entries)
        for name in names:
            if stopped():
                raise InterruptedError("Source scan stopped")
            rel = prefix + name
            child = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=fd)
            try:
                mode = os.fstat(child).st_mode
                if stat.S_ISDIR(mode):
                    walk(child, rel + "/")
                else:
                    rows[rel] = read_file(child, stopped=stopped)
                if signature(os.fstat(child)) != signature(os.stat(name, dir_fd=fd, follow_symlinks=False)):
                    raise ValueError("Source changed during inventory")
            finally:
                os.close(child)
        if before != signature(os.fstat(fd)):
            raise ValueError("Directory changed during inventory")

    with opened(path, directory=source["kind"] == "directory") as fd:
        if source["kind"] == "directory":
            walk(fd)
        else:
            rows[path.name] = read_file(fd, stopped=stopped)
    return rows

def request(path, method="GET", payload=None):
    token = Path(cfg["token_file"]).read_text().strip()
    req = Request(
        f"http://127.0.0.1:{cfg['port']}" + path,
        method=method,
        data=json.dumps(payload).encode() if payload is not None else None,
        headers={"Authorization": "Bearer " + token, "Content-Type": "application/json"},
    )
    try:
        with urlopen(req, timeout=300) as response:
            return json.load(response)
    except HTTPError as exc:
        body = exc.read(8192).decode(errors="replace")
        raise ValueError(f"Graf returned HTTP {exc.code}: {body}") from None

def _stat_signature(value):
    # Reading a file/directory can change atime on relatime mounts. Access time
    # is not a content mutation and must not invalidate our own read-only scan.
    return (value.st_dev, value.st_ino, value.st_mode, value.st_size,
            value.st_mtime_ns, value.st_ctime_ns)
